if (!status || status >= 300) reason = `llm-http-${status || 'no-response'}`;
else {
  answer = ftwParseJson(ftwLlmText(payload));
  if (!answer || !answer.why_it_matters) { answer = null; reason = 'unparseable-answer'; }
}

const bullets = a => (a.length ? a.map(x => `- ${x}`).join('\n') : '- _None identified._');
let body;
if (answer) {
  body = [
    marker, '### AI pull request summary', '',
    '**What changed**', bullets(ftwSafeList(answer.what_changed, 8)), '',
    '**Why it matters**', ftwSafe(answer.why_it_matters, 800), '',
    '**Risk notes**', bullets(ftwSafeList(answer.risks, 6)), '',
    '**Suggested review focus**', bullets(ftwSafeList(answer.review_focus, 6)), '',
    `<sub>${notes.join(' · ')} · ${ftwSafe(S.llm.model, 60)} · AI-generated, verify before relying on it.</sub>`,
  ].join('\n');
} else {
  if (String(C.on_llm_failure || 'note') === 'skip') return [];
  body = [
    marker, '### AI pull request summary unavailable', '',
    `The summary for ${notes[0]} could not be generated (\`${reason}\`). Nothing was guessed.`, '',
    `<sub>${notes.slice(1).join(' · ')}</sub>`,
  ].join('\n');
}
return [{ json: { marker, body, ok: !!answer, reason } }];

// ---- redaction: runs before any diff text is sent to the model ----
const REDACTION_RULES = [
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(?:-----END [A-Z ]*PRIVATE KEY-----|$)/g, '[REDACTED:private_key]'],
  [/\b([a-z][a-z0-9+.-]*:\/\/)[^\s:@\/"'<>]+:[^\s@\/"'<>]+@/gi, '$1[REDACTED:credentials]@'],
  [/\b(?:AKIA|ASIA|AGPA|AIDA|AROA|ANPA)[0-9A-Z]{16}\b/g, '[REDACTED:aws_access_key]'],
  [/\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, '[REDACTED:jwt]'],
  [/\b(Bearer|Basic|Token)\s+[A-Za-z0-9._~+\/=-]{8,}/g, '$1 [REDACTED:token]'],
  [/\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/g, '[REDACTED:github_token]'],
  [/\bxox[abposr]-[A-Za-z0-9-]{10,}/g, '[REDACTED:slack_token]'],
  [/\bsk-(?:proj-|ant-(?:api\d+-)?)?[A-Za-z0-9_-]{20,}/g, '[REDACTED:api_key]'],
  [/\b((?:[a-z0-9]+[_-])*(?:password|passwd|pwd|secret|token|api[_-]?key|apikey|access[_-]?key|private[_-]?key|client[_-]?secret|credentials?))(["'\s]*[:=]\s*["']?)([^\s"'\\&,;}\]]{6,})/gi, '$1$2[REDACTED]'],
];

function ftwRedact(text) {
  let out = text == null ? '' : String(text);
  let count = 0;
  for (const [rx, repl] of REDACTION_RULES) {
    out = out.replace(rx, (...m) => { count++; return repl.replace(/\$(\d)/g, (_, i) => m[Number(i)] || ''); });
  }
  return { text: out, count };
}

// ---- glob matching for the ignore list (*, **, ? only: no shell, no dependencies) ----
function ftwGlobToRegExp(glob) {
  let rx = '';
  const g = String(glob);
  for (let i = 0; i < g.length; i++) {
    const c = g[i];
    if (c === '*') {
      if (g[i + 1] === '*') { rx += '.*'; i++; if (g[i + 1] === '/') i++; }
      else rx += '[^/]*';
    } else if (c === '?') rx += '[^/]';
    else rx += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp('^' + rx + '$');
}
function ftwMatchesAny(path, globs) {
  return (globs || []).some(g => {
    try { return ftwGlobToRegExp(g).test(path) || ftwGlobToRegExp(g).test(path.split('/').pop()); }
    catch (e) { return false; }
  });
}

// ---- text coming back from the model: never trusted as Markdown ----
function ftwSafe(text, max) {
  return String(text == null ? '' : text)
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '')
    .replace(/<!--/g, '<! --')                      // cannot forge the comment marker
    .replace(/^\s*(#{1,6})\s/gm, '')                // no headings that break the comment layout
    .replace(/@([a-zA-Z0-9-])/g, '@\u200b$1')       // no mass @-mentions from model output
    .trim()
    .slice(0, max || 800);
}
function ftwSafeList(list, n) {
  return (Array.isArray(list) ? list : []).slice(0, n || 8).map(x => ftwSafe(x, 300)).filter(Boolean);
}

// ---- parse the model's answer: bare JSON, or JSON inside a ```json fence ----
function ftwParseJson(text) {
  const t = String(text || '').trim();
  const fenced = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  for (const c of [fenced ? fenced[1] : null, t, (t.match(/\{[\s\S]*\}/) || [])[0]]) {
    if (!c) continue;
    try {
      const o = JSON.parse(c);
      if (o && typeof o === 'object' && !Array.isArray(o)) return o;
    } catch (e) { /* try the next candidate */ }
  }
  return null;
}

function ftwLlmText(payload) {
  if (!payload || typeof payload !== 'object') return '';
  const choice = (payload.choices || [])[0] || {};
  const msg = choice.message || {};
  if (typeof msg.content === 'string') return msg.content;
  if (Array.isArray(msg.content)) return msg.content.map(p => (p && p.text) || '').join('');
  return typeof choice.text === 'string' ? choice.text : '';
}

// Collect the body of one or more HTTP Request items (pagination produces one item per page).
function ftwPages(items) {
  const out = [];
  for (const it of items) {
    const r = it.json || {};
    let body = r.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
    const status = Number(r.statusCode || 0);
    if (!status || status >= 300) {
      throw new Error(`GitHub API returned HTTP ${status || 'no response'}: ${JSON.stringify(body).slice(0, 300)}`);
    }
    if (Array.isArray(body)) out.push(...body);
    else if (body) out.push(body);
  }
  return out;
}

// One comment per pull request: update the previous summary if this workflow already wrote one,
// otherwise create it. Matching is on the hidden marker, so human comments are never touched.
const v = $('Verify delivery').first().json;
const rendered = $('Render comment').first().json;
const comments = ftwPages($input.all());
const mine = comments.filter(c => String((c || {}).body || '').includes(rendered.marker));
const existing = mine.length ? mine[mine.length - 1] : null;
return [{
  json: {
    method: existing ? 'PATCH' : 'POST',
    url: existing ? `${v.comment_base}/${existing.id}` : v.comments_api,
    json_body: JSON.stringify({ body: rendered.body }),
    action: existing ? 'updated' : 'created',
    comment_id: existing ? existing.id : null,
  },
}];
